     ((-1 + \[Xi]w)^2*mass[MW]^4) + 
    ((-2 + d)*mtad[{Sqrt[\[Xi]w]*mass[MW], 0, Sqrt[\[Xi]w]*mass[MW]}, 
       {1, 0, 1}])/(2*(-3 + d)*(-1 + \[Xi]w)^2*mass[MW]^6) + 
    (\[Xi]w^2*mtad[{Sqrt[\[Xi]w]*mass[MW], mass[MW], mass[MW]}, {1, 1, 1}])/
     ((-1 + \[Xi]w)^3*mass[MW]^4) - 
    (\[Xi]w^2*mtad[{Sqrt[\[Xi]w]*mass[MW], mass[MW], Sqrt[\[Xi]w]*mass[MW]}, 
       {1, 1, 1}])/((-1 + \[Xi]w)^3*mass[MW]^4) - 
    (\[Xi]w*mtad[{Sqrt[\[Xi]w]*mass[MW], Sqrt[\[Xi]w]*mass[MW], mass[MW]}, 
       {1, 1, 1}])/((-1 + \[Xi]w)^3*mass[MW]^4) + 
    (\[Xi]w*mtad[{Sqrt[\[Xi]w]*mass[MW], Sqrt[\[Xi]w]*mass[MW], 
        Sqrt[\[Xi]w]*mass[MW]}, {1, 1, 1}])/((-1 + \[Xi]w)^3*mass[MW]^4)))/
  (4096*d*Pi^8*sw^2)
